import pandas as pd


def add_features(rows):
    if len(rows) == 0:
        return []
    df = pd.DataFrame(rows)
    ratios = []
    for price, area in zip(df["price"], df["area"]):
        ratios.append(None if area == 0 else round(float(price) / float(area), 2))
    df["price_per_sqft"] = ratios
    df["age_bucket"] = pd.cut(df["age"], bins=[0, 2, 5, 10],
                              labels=["new", "mid", "old"]).astype(object)
    df = df.where(pd.notna(df), None)
    return df.to_dict(orient="records")
